<?php
/** Teacher and Student Portals, 4.7.0. Uses existing authentication, academic/LMS/CBT records. */
if (!defined('SCHOOLOS_LEARNING_LIBRARY')) { header('Location: index.php?s=learning', true, 302); exit; }
function lp_schema(): array { return [
 "CREATE TABLE IF NOT EXISTS lp_corrections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,score_id BIGINT UNSIGNED NOT NULL,requested_by BIGINT UNSIGNED NOT NULL,previous_score DECIMAL(8,2) NOT NULL,new_score DECIMAL(8,2) NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by BIGINT UNSIGNED NULL,review_note VARCHAR(1000) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_pd(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,provider VARCHAR(180) NOT NULL,completed_on DATE NOT NULL,hours DECIMAL(6,2) NOT NULL,evidence_url VARCHAR(1000) NULL,status VARCHAR(20) NOT NULL DEFAULT 'submitted',reviewed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_clubs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,capacity INT NOT NULL DEFAULT 30,active TINYINT NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED NOT NULL,INDEX(tenant_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_club_members(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,club_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_member(tenant_id,club_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_library_loans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'requested',due_on DATE NULL,reviewed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,returned_at DATETIME NULL,INDEX(tenant_id,book_id,status),INDEX(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_planner(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,due_on DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'planned',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,user_id,due_on)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_ai_settings(tenant_id BIGINT UNSIGNED PRIMARY KEY,teachers_enabled TINYINT NOT NULL DEFAULT 0,students_enabled TINYINT NOT NULL DEFAULT 0,daily_limit INT NOT NULL DEFAULT 5) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lp_ai_usage(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,usage_day DATE NOT NULL,request_count INT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,user_id,usage_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ]; }
function lp_install(): void { global $pdo; foreach (['ecosystem_links','books','students','users'] as $t) if(!lp_has($t))throw new RuntimeException('Activate the core ecosystem first.'); acInstall(); lmInstall(); cbInstall(); awInstall(); if(function_exists('pp_install'))pp_install(); foreach(lp_schema() as $s)$pdo->exec($s); }
function lp_has(string $table): bool { return (bool)g('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[$table]); }
function lp_ready(): bool { foreach(['lp_corrections','lp_pd','lp_clubs','lp_club_members','lp_library_loans','lp_planner','lp_ai_settings','lp_ai_usage','ac_allocations','lm_courses','cb_exams','aw_cases','pp_requests'] as $t)if(!lp_has($t))return false; return true; }
function lp_actor(): array {
 $u=me(); if(!$u||!in_array($u['role']??'',['school_admin','teacher','student'],true)||(int)($u['tenant_id']??0)<1)throw new RuntimeException('School teacher, student or administrator access required.');
 if(!g('SELECT id FROM users WHERE id=? AND tenant_id=? AND role=? AND active=1',[$u['id'],$u['tenant_id'],$u['role']]))throw new RuntimeException('Account is no longer active.'); return $u;
}
function lp_text(string $key,int $max=2000,bool $required=false): string { $v=$_POST[$key]??''; if(!is_string($v))throw new RuntimeException('Invalid input: '.$key); $v=trim($v); if(mb_strlen($v)>$max||($required&&$v===''))throw new RuntimeException('Check '.$key.'.');return $v; }
function lp_num(string $raw,float $max): float { if(!preg_match('/^\d+(?:\.\d{1,2})?$/D',$raw)||!is_finite((float)$raw)||(float)$raw>$max)throw new RuntimeException('Number must be between zero and '.(string)$max.'.');return (float)$raw; }
function lp_date(string $v): string { $d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new RuntimeException('Invalid calendar date.');return $v; }
function lp_datetime(string $v): ?string { if($v==='')return null;$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$v);if(!$d||$d->format('Y-m-d\TH:i')!==$v)throw new RuntimeException('Invalid date/time.');return $d->format('Y-m-d H:i:s'); }
function lp_url(string $url): string { if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'))throw new RuntimeException('Resource links must use HTTPS.');return $url; }
function lp_student(array $u): array {
 if($u['role']!=='student')throw new RuntimeException('Student access required.');
 $rows=q("SELECT DISTINCT s.*,c.session_name,c.name class_name FROM ecosystem_links l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id LEFT JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id WHERE l.tenant_id=? AND l.user_id=? AND l.relation_type='student'",[$u['tenant_id'],$u['id']])->fetchAll();
 if(count($rows)!==1)throw new RuntimeException('Ask the school to link this account to exactly one student record.');return $rows[0];
}
function lp_assignments(array $u): array {
 $tid=(int)$u['tenant_id'];if($u['role']==='school_admin')return q('SELECT c.id class_id,c.name class_name,c.session_name,s.id subject_id,s.name subject_name FROM classes c JOIN subjects s ON s.tenant_id=c.tenant_id WHERE c.tenant_id=? ORDER BY c.name,s.name',[$tid])->fetchAll();
 return q('SELECT a.class_id,a.subject_id,a.session_name,c.name class_name,s.name subject_name FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id JOIN subjects s ON s.id=a.subject_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.teacher_id=? AND a.session_name=c.session_name ORDER BY c.name,s.name',[$tid,$u['id']])->fetchAll();
}
function lp_scope(array $u,int $class,int $subject=0,?string $session=null): array {
 if(!in_array($u['role'],['teacher','school_admin'],true))throw new RuntimeException('Teacher access required.');
 foreach(lp_assignments($u) as $a)if((int)$a['class_id']===$class&&(!$subject||(int)$a['subject_id']===$subject)&&($session===null||$session===$a['session_name']))return $a;
 throw new RuntimeException('Class, subject or session is outside your current allocation.');
}
function lp_pupil(array $u,int $sid): array { $s=q('SELECT * FROM students WHERE tenant_id=? AND id=?',[$u['tenant_id'],$sid])->fetch();if(!$s)throw new RuntimeException('Student unavailable.');lp_scope($u,(int)$s['class_id']);return $s; }
function lp_course(array $u,int $id,bool $edit=false): array {
 $c=q('SELECT * FROM lm_courses WHERE tenant_id=? AND id=?',[$u['tenant_id'],$id])->fetch();if(!$c)throw new RuntimeException('Course unavailable.');
 if($u['role']==='student'){$s=lp_student($u);if($edit||$c['status']!=='published'||(int)$c['class_id']!==(int)$s['class_id'])throw new RuntimeException('Course unavailable.');}
 else {lp_scope($u,(int)$c['class_id'],(int)$c['subject_id']);if($edit&&$u['role']==='teacher'&&(int)$c['teacher_id']!==(int)$u['id'])throw new RuntimeException('This course belongs to another teacher.');}return $c;
}
function lp_assessment(array $u,int $id,bool $lock=false): array {
 $a=q('SELECT * FROM ac_assessments WHERE tenant_id=? AND id=?'.($lock?' FOR UPDATE':''),[$u['tenant_id'],$id])->fetch();if(!$a)throw new RuntimeException('Assessment unavailable.');lp_scope($u,(int)$a['class_id'],(int)$a['subject_id'],$a['session_name']);return $a;
}
function lp_save_scores(array $u,int $assessment,array $rows): void {
 global $pdo;if(!$rows||count($rows)>500)throw new RuntimeException('Use 1–500 score rows.');$tid=(int)$u['tenant_id'];$pdo->beginTransaction();try{
  $a=lp_assessment($u,$assessment,true);
  // Lock the class to serialize publication with portal score operations; recheck current publication.
  q('SELECT id FROM classes WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$a['class_id']]);
  if(acPublished($tid,(int)$a['class_id'],$a['session_name'],$a['term_name']))throw new RuntimeException('Published results are locked.');
  $seen=[];foreach($rows as $r){$sid=(int)$r['student_id'];if(isset($seen[$sid]))throw new RuntimeException('Duplicate student row.');$seen[$sid]=true;
   $s=q('SELECT class_id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$sid])->fetch();if(!$s||(int)$s['class_id']!==(int)$a['class_id'])throw new RuntimeException('Student is outside assessment class.');$score=lp_num((string)$r['score'],(float)$a['max_score']);
   $old=q('SELECT * FROM ac_scores WHERE tenant_id=? AND assessment_id=? AND student_id=? FOR UPDATE',[$tid,$assessment,$sid])->fetch();if($old&&$old['status']!=='draft')throw new RuntimeException('Submitted/approved scores require a correction request.');
   q("INSERT INTO ac_scores(tenant_id,assessment_id,student_id,score,status,entered_by) VALUES(?,?,?,?,'draft',?) ON DUPLICATE KEY UPDATE score=VALUES(score),entered_by=VALUES(entered_by)",[$tid,$assessment,$sid,$score,$u['id']]);
  }audit('learning.scores.saved','assessment',(string)$assessment);$pdo->commit();
 }catch(Throwable $e){$pdo->rollBack();throw $e;}
}
function lp_parse_scores(array $u,int $aid,string $csv): array {
 if(strlen($csv)>262144)throw new RuntimeException('CSV must be under 256 KB.');$a=lp_assessment($u,$aid);$f=fopen('php://temp','r+');fwrite($f,$csv);rewind($f);
 try{$head=fgetcsv($f,0,',','"','');if($head!==['student_no','score'])throw new RuntimeException('CSV header must be student_no,score.');$rows=[];$seen=[];
  while(($r=fgetcsv($f,0,',','"',''))!==false){if($r===[null])continue;if(count($r)!==2||count($rows)>=500)throw new RuntimeException('Invalid CSV row or row limit.');$no=trim($r[0]);if(isset($seen[$no]))throw new RuntimeException('Duplicate student number.');$seen[$no]=true;
   $s=q('SELECT id FROM students WHERE tenant_id=? AND class_id=? AND student_no=?',[$u['tenant_id'],$a['class_id'],$no])->fetchAll();if(count($s)!==1)throw new RuntimeException('Unknown or ambiguous student number: '.$no);
   $rows[]=['student_id'=>(int)$s[0]['id'],'score'=>lp_num(trim($r[1]),(float)$a['max_score'])];
  }if(!$rows)throw new RuntimeException('CSV has no score rows.');return $rows;
 }finally{fclose($f);}
}
function lp_exam(array $u,int $id,bool $edit=false): array {
 $x=cbExam((int)$u['tenant_id'],$id);lp_scope($u,(int)$x['class_id'],(int)$x['subject_id']);
 if($edit&&($x['published']||($u['role']==='teacher'&&(int)$x['created_by']!==(int)$u['id'])||(int)g('SELECT COUNT(*) FROM cb_attempts WHERE tenant_id=? AND exam_id=?',[$u['tenant_id'],$id])))throw new RuntimeException('Question bank is locked or belongs to another teacher.');return $x;
}
function lp_cbt_start(array $u,int $id,string $code): int {
 global $pdo;$s=lp_student($u);$tid=(int)$u['tenant_id'];$pdo->beginTransaction();try{
  q('SELECT id FROM users WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$u['id']]);
  $x=q('SELECT * FROM cb_exams WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();$now=date('Y-m-d H:i:s');
  if(!$x||!$x['published']||(int)$x['class_id']!==(int)$s['class_id']||($x['starts_at']&&$x['starts_at']>$now)||($x['ends_at']&&$x['ends_at']<=$now))throw new RuntimeException('Exam is not available to your class at this time.');
  if($x['access_code']!==''&&!hash_equals($x['access_code'],$code))throw new RuntimeException('Invalid exam access code.');
  $active=q('SELECT * FROM cb_attempts WHERE tenant_id=? AND exam_id=? AND student_id=? AND submitted_at IS NULL FOR UPDATE',[$tid,$id,$s['id']])->fetch();
  if($active){if((int)$active['user_id']!==(int)$u['id'])throw new RuntimeException('An attempt exists under a different account. Ask the school to review.');if($active['expires_at']>$now){$pdo->commit();return (int)$active['id'];}cbFinalize($tid,(int)$active['id']);}
  if((int)g('SELECT COUNT(*) FROM cb_attempts WHERE tenant_id=? AND exam_id=? AND student_id=?',[$tid,$id,$s['id']])>=(int)$x['attempt_limit']){$pdo->commit();throw new RuntimeException('Attempt limit reached.');}
  $questions=q('SELECT id,points FROM cb_questions WHERE tenant_id=? AND exam_id=? ORDER BY id',[$tid,$id])->fetchAll();if(!$questions)throw new RuntimeException('Exam has no questions.');if($x['randomize'])shuffle($questions);if((int)$x['question_limit']>0)$questions=array_slice($questions,0,(int)$x['question_limit']);
  $ids=array_map(fn($r)=>(int)$r['id'],$questions);$max=array_sum(array_column($questions,'points'));$expires=(new DateTimeImmutable())->modify('+'.max(1,min(300,(int)$x['duration_minutes'])).' minutes')->format('Y-m-d H:i:s');if($x['ends_at']&&$x['ends_at']<$expires)$expires=$x['ends_at'];
  q('INSERT INTO cb_attempts(tenant_id,exam_id,student_id,user_id,started_at,expires_at,question_order_json,max_score) VALUES(?,?,?,?,?,?,?,?)',[$tid,$id,$s['id'],$u['id'],$now,$expires,json_encode($ids),$max]);$aid=(int)$pdo->lastInsertId();foreach($ids as $qid)q('INSERT INTO cb_answers(tenant_id,attempt_id,question_id) VALUES(?,?,?)',[$tid,$aid,$qid]);cbEvent($tid,$aid,'started');$pdo->commit();return $aid;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function lp_cbt_save(array $u,int $id,array $answers,bool $submit): string {
 global $pdo;$s=lp_student($u);$tid=(int)$u['tenant_id'];$pdo->beginTransaction();try{
  $a=q('SELECT * FROM cb_attempts WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();if(!$a||(int)$a['user_id']!==(int)$u['id']||(int)$a['student_id']!==(int)$s['id'])throw new RuntimeException('Attempt unavailable.');if($a['submitted_at'])throw new RuntimeException('Attempt already submitted.');
  if($a['expires_at']<=date('Y-m-d H:i:s')){cbFinalize($tid,$id);$pdo->commit();return 'Time expired. Previously saved answers were submitted.';}
  $allowed=json_decode($a['question_order_json'],true,512,JSON_THROW_ON_ERROR);foreach($answers as $qid=>$v){if(!in_array((int)$qid,$allowed,true)||!is_string($v)||mb_strlen($v)>12000)throw new RuntimeException('Invalid exam answer.');q('UPDATE cb_answers SET response=? WHERE tenant_id=? AND attempt_id=? AND question_id=?',[$v,$tid,$id,(int)$qid]);}
  if($submit)cbFinalize($tid,$id);$pdo->commit();return $submit?'Exam submitted. Results appear after school publication.':'Answers saved. The timer continues.';
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function lp_ai_api(string $path,array $payload,string $key): array {
 $ch=curl_init('https://api.openai.com/v1/'.$path);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key,'Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);
