}
function lp_ai(array $u,string $prompt,?callable $transport=null): string {
 global $pdo,$c;$tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$student=$u['role']==='student';if(!in_array($u['role'],['student','teacher'],true))throw new RuntimeException('Teacher or student account required.');if($student)$s=lp_student($u);
