 $prompt=preg_replace(['/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i','/\+?\d[\d ()-]{8,}\d/','/\b(?:my name is|student name|address|date of birth)\s*[:=]?[^\n.;]+/iu'],['[email removed]','[number removed]','[personal details removed]'],$prompt);
 $key=(string)($c['providers']['ai_api_key']??'');if($key==='')throw new RuntimeException('School AI provider key is not configured. Ask your administrator; never post keys in chat.');
