function lp_filter(array $u,string $alias): array {
 if(!preg_match('/^[a-z]+$/D',$alias))throw new LogicException('Invalid internal alias.');
 if($u['role']==='school_admin')return ['1=1',[]];
 if($u['role']==='student'){$s=lp_student($u);return [$alias.'.class_id=?',[(int)$s['class_id']]];}
 return ["EXISTS (SELECT 1 FROM ac_allocations la JOIN classes lc ON lc.id=la.class_id AND lc.tenant_id=la.tenant_id WHERE la.tenant_id=$alias.tenant_id AND la.teacher_id=? AND la.class_id=$alias.class_id AND la.subject_id=$alias.subject_id AND la.session_name=lc.session_name)",[(int)$u['id']]];
}
function lp_courses(array $u): array {[$f,$p]=lp_filter($u,'c');return q('SELECT c.* FROM lm_courses c WHERE c.tenant_id=? AND '.$f.($u['role']==='teacher'?' AND c.teacher_id=?':($u['role']==='student'?" AND c.status='published'":'')).' ORDER BY c.id DESC LIMIT 100',array_merge([$u['tenant_id']],$p,$u['role']==='teacher'?[$u['id']]:[]))->fetchAll();}
function lp_roster(array $u): array {
 if($u['role']==='school_admin')return q('SELECT id,name,student_no,class_id FROM students WHERE tenant_id=? ORDER BY name LIMIT 1000',[$u['tenant_id']])->fetchAll();
 return q('SELECT s.id,s.name,s.student_no,s.class_id FROM students s WHERE s.tenant_id=? AND EXISTS(SELECT 1 FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=s.tenant_id AND a.class_id=s.class_id AND a.teacher_id=? AND a.session_name=c.session_name) ORDER BY s.name LIMIT 1000',[$u['tenant_id'],$u['id']])->fetchAll();
}
function lp_topics(array $u): array {[$f,$p]=lp_filter($u,'t');return q('SELECT t.* FROM ac_curriculum t JOIN classes c ON c.id=t.class_id AND c.tenant_id=t.tenant_id WHERE t.tenant_id=? AND t.session_name=c.session_name AND '.$f.' ORDER BY t.week_no,t.id LIMIT 300',array_merge([$u['tenant_id']],$p))->fetchAll();}
function lp_assessments(array $u): array {[$f,$p]=lp_filter($u,'a');return q('SELECT a.* FROM ac_assessments a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.session_name=c.session_name AND '.$f.' ORDER BY a.id DESC LIMIT 200',array_merge([$u['tenant_id']],$p))->fetchAll();}
function lp_download(array $u,int $id): void {
 $r=q('SELECT s.*,l.course_id FROM lm_submissions s JOIN lm_lessons l ON l.id=s.lesson_id AND l.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.id=?',[$u['tenant_id'],$id])->fetch();if(!$r||$r['filedata']===null)throw new RuntimeException('Attachment unavailable.');
 if($u['role']==='student'){if((int)lp_student($u)['id']!==(int)$r['student_id'])throw new RuntimeException('Attachment unavailable.');}else lp_course($u,(int)$r['course_id'],true);
 header('Content-Type: '.$r['filemime']);header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',basename($r['filename'])).'"');echo $r['filedata'];exit;
}
function lp_form(string $action): void {echo '<form method="post" enctype="multipart/form-data" class="lp-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="lp_action" value="'.e($action).'">';}
function lp_hidden(string $key,int $id): void {echo '<input type="hidden" name="'.e($key).'" value="'.$id.'">';}
function lp_input(string $key,string $label,string $type='text',string $value='',bool $required=true): void {echo '<label>'.e($label);if($type==='textarea')echo '<textarea name="'.e($key).'" rows="4"'.($required?' required':'').'>'.e($value).'</textarea>';else echo '<input name="'.e($key).'" type="'.e($type).'" value="'.e($value).'"'.($type==='number'?' step="0.01" min="0"':'').($required?' required':'').'>';echo '</label>';}
function lp_select(string $key,string $label,array $choices): void {echo '<label>'.e($label).'<select name="'.e($key).'" required>';foreach($choices as $id=>$text)echo '<option value="'.e($id).'">'.e($text).'</option>';echo '</select></label>';}
function lp_choices(array $rows,string $label='title',string $id='id'): array {$out=[];foreach($rows as $r)$out[$r[$id]]=$r[$label].' #'.$r[$id];return $out;}
function lp_end(string $label): void {echo '<div><button class="btn">'.e($label).'</button></div></form>';}
function lp_table(array $rows,array $headers): void {echo '<div class="lp-scroll"><table class="table"><tr>';foreach($headers as $h)echo '<th>'.e($h).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e($v).'</td>';echo '</tr>';}echo '</table></div>';if(!$rows)echo '<p class="muted">No records available yet.</p>';}
function lp_card(string $title): void {echo '<section class="lp-card"><h3>'.e($title).'</h3>';}
function lp_class_fields(array $u): void {$as=lp_assignments($u);$classes=[];$subjects=[];foreach($as as $a){$classes[$a['class_id']]=$a['class_name'];$subjects[$a['subject_id']]=$a['subject_name'];}lp_select('class_id','Assigned class',$classes);lp_select('subject_id','Assigned subject',$subjects);echo '<p class="muted">Choose an allocated class and subject combination. The server checks your allocation.</p>';}
function lp_render(array $u): void {
 $teacher=$u['role']!=='student';$admin=$u['role']==='school_admin';$tid=(int)$u['tenant_id'];
 echo '<style>.lp-hero{background:linear-gradient(110deg,#14344d,#087e73);color:white;border-radius:18px;padding:25px}.lp-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.lp-tabs a{padding:9px 13px;border:1px solid var(--line);border-radius:10px;color:var(--ink);text-decoration:none;background:var(--card-bg)}.lp-tabs a[aria-current=page]{background:#086e65;color:white}.lp-card{background:var(--card-bg);border:1px solid var(--line);border-radius:16px;padding:22px;margin:16px 0}.lp-card p,.lp-answer{white-space:pre-wrap;overflow-wrap:anywhere}.lp-scroll{overflow:auto}.lp-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.lp-form label{display:grid;gap:7px;font-size:13px}.lp-form input,.lp-form textarea,.lp-form select{width:100%;padding:11px;background:var(--field-bg);color:var(--field-text);border:1px solid var(--line);border-radius:9px;font:inherit}.lp-form label:has(textarea){grid-column:1/-1}.lp-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.lp-metric{background:var(--card-bg);padding:20px;border:1px solid var(--line);border-radius:14px}.lp-metric strong{display:block;font-size:28px}.lp-chip{font-size:12px;border-radius:15px;padding:5px 9px;background:#e3f5ef;color:#075f51}.lp-timer{position:sticky;top:80px;z-index:4;padding:14px;background:#123f50;color:white;border-radius:12px}@media(max-width:650px){.lp-form,.lp-metrics{grid-template-columns:1fr}.lp-card{padding:16px}}</style>';
 echo '<div class="lp-hero"><span>SCHOOLOS LEARNING</span><h2>'.($admin?'Learning Portals · school workspace':($teacher?'Teacher Portal':'Student Portal')).'</h2><p>'.($teacher?'Plan, teach and support your assigned learners.':'Your learning, progress and school life in one place.').'</p></div>';
 if(!lp_ready()){lp_card('Activate Teacher & Student Portals');echo '<p>Adds portal tables and prepares existing Academics, LMS, CBT and Welfare schemas without deleting records. Back up your database first.</p>';if($admin){lp_form('activate');lp_end('Activate Learning Portals');}else echo '<p>Ask your school administrator to activate Learning Portals.</p>';echo '</section>';return;}
 $tabs=$teacher?['classes'=>'Assigned classes','attendance'=>'Attendance','timetable'=>'Timetable','lessons'=>'Lesson plans','syllabus'=>'Syllabus progress','assignments'=>'Assignments','questions'=>'Question banks','scores'=>'Score entry','bulk'=>'Bulk uploads','corrections'=>'Corrections','analytics'=>'Performance analytics','messages'=>'Parent messaging','resources'=>'Teaching resources','incidents'=>'Incidents','leave'=>'Leave','pd'=>'Professional development','ai'=>'AI lesson assistance']:['dashboard'=>'Dashboard','timetable'=>'Timetable','homework'=>'Homework','resources'=>'Learning resources','cbt'=>'CBT','grades'=>'Grades','attendance'=>'Attendance','feedback'=>'Teacher feedback','announcements'=>'Announcements','clubs'=>'Clubs','library'=>'Library','badges'=>'Badges','planner'=>'Study planner','ai'=>'Safeguarded AI study support'];
 if($admin)$tabs['manage']='School approvals';$view=is_string($_GET['view']??null)?$_GET['view']:array_key_first($tabs);if(!isset($tabs[$view]))$view=array_key_first($tabs);
 echo '<nav class="lp-tabs" aria-label="Learning portal features">';foreach($tabs as $key=>$label)echo '<a href="?s=learning&amp;view='.$key.'" '.($key===$view?'aria-current="page"':'').'>'.e($label).'</a>';echo '</nav>';
 if(!$teacher){$s=lp_student($u);echo '<p><span class="lp-chip">'.e($s['name'].' · '.$s['student_no'].' · '.$s['class_name']).'</span></p>';}
 if($view==='ai'){lp_card($tabs[$view]);echo '<p>'.($teacher?'Generate a lesson draft to review and adapt before teaching.':'Ask for hints, explanations and practice. Do not enter names, contact details or private information. Assistance pauses during active CBT.').'</p>';echo '<p class="muted">School-enabled OpenAI integration · daily request limits · moderated input and output. AI may make mistakes. No grades or school records are sent.</p>';lp_form('ai');lp_input('prompt',$teacher?'Topic, class level and lesson goal':'What would you like to understand?','textarea');lp_end('Ask for assistance');if(isset($_SESSION['lp_ai_result'])){echo '<div class="lp-answer" role="status">'.e($_SESSION['lp_ai_result']).'</div>';unset($_SESSION['lp_ai_result']);}echo '</section>';return;}
 if($view==='timetable'){
  [$f,$p]=lp_filter($u,'t');$sql='SELECT t.weekday,t.start_time,t.end_time,s.name subject,c.name class_name,t.room,t.session_name FROM ac_timetable t JOIN subjects s ON s.id=t.subject_id AND s.tenant_id=t.tenant_id JOIN classes c ON c.id=t.class_id AND c.tenant_id=t.tenant_id WHERE t.tenant_id=? AND t.session_name=c.session_name AND '.$f.($u['role']==='teacher'?' AND t.teacher_id=?':'').' ORDER BY t.weekday,t.start_time';lp_card('Weekly timetable · Africa/Lagos');lp_table(q($sql,array_merge([$tid],$p,$u['role']==='teacher'?[$u['id']]:[]))->fetchAll(),['Weekday (Mon=1)','Start','End','Subject','Class','Room','Session']);echo '</section>';return;
 }
 if($teacher)lp_teacher_view($u,$view);else lp_student_view($u,$s,$view);
}
