 $tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$admin=$u['role']==='school_admin';$roster=lp_roster($u);$pupils=lp_choices($roster,'name');$topics=lp_topics($u);$courses=lp_courses($u);$assessments=lp_assessments($u);
