   foreach($topics as $t){$rows=q('SELECT lesson_date,plan,homework,status FROM ac_lessons WHERE tenant_id=? AND curriculum_id=?'.($admin?'':' AND teacher_id=?').' ORDER BY id DESC LIMIT 20',$admin?[$tid,$t['id']]:[$tid,$t['id'],$uid])->fetchAll();if($rows){echo '<h4>'.e($t['topic']).'</h4>';lp_table($rows,['Date','Plan','Homework','Status']);}}
  }else{lp_table(array_map(fn($r)=>[$r['id'],$r['topic'],$r['week_no'],$r['coverage']],$topics),['Topic ID','Topic','Week','Progress']);lp_form('coverage');lp_select('curriculum_id','Syllabus topic',lp_choices($topics,'topic'));lp_select('coverage','Progress',['planned'=>'Planned','in_progress'=>'In progress','completed'=>'Completed']);lp_end('Update syllabus progress');}
 }
 elseif($view==='assignments'){
