   $rows=q('SELECT s.*,l.title,l.points,st.name learner FROM lm_submissions s JOIN lm_lessons l ON l.id=s.lesson_id AND l.tenant_id=s.tenant_id JOIN students st ON st.id=s.student_id AND st.tenant_id=s.tenant_id WHERE s.tenant_id=? AND l.course_id=? ORDER BY s.id DESC LIMIT 100',[$tid,$course['id']])->fetchAll();
   foreach($rows as $r){echo '<article><h4>'.e($r['learner'].' · '.$r['title']).'</h4><p>'.e($r['answer']).'</p>';if($r['filedata']!==null)echo '<a href="?s=learning&amp;lp_file='.(int)$r['id'].'">Download homework attachment</a>';lp_form('grade');lp_hidden('submission_id',(int)$r['id']);lp_input('score','Score / '.$r['points'],'number',(string)($r['score']??''));lp_input('feedback','Teacher feedback','textarea',(string)($r['feedback']??''));lp_end('Save grade and feedback');echo '</article>';}
  }
 }
