  [$f,$p]=lp_filter($u,'x');$exams=q('SELECT x.* FROM cb_exams x WHERE x.tenant_id=? AND '.$f.($admin?'':' AND x.created_by=?').' ORDER BY x.id DESC LIMIT 100',array_merge([$tid],$p,$admin?[]:[$uid]))->fetchAll();
