   $preview=$_SESSION['lp_bulk']??null;if($preview&&$preview['user']===$uid&&$preview['tenant']===$tid&&$preview['expires']>time()){lp_table(array_map(fn($r)=>[$r['student_id'],$r['score']],$preview['rows']),['Student ID','Draft score']);lp_form('bulk_commit');lp_end('Confirm import of all preview rows');}
