  $scores=[];foreach($assessments as $as){$rows=q('SELECT sc.id,st.name,sc.score,sc.status FROM ac_scores sc JOIN students st ON st.id=sc.student_id AND st.tenant_id=sc.tenant_id WHERE sc.tenant_id=? AND sc.assessment_id=? ORDER BY st.name LIMIT 500',[$tid,$as['id']])->fetchAll();foreach($rows as $r)$scores[]=array_merge([$as['title']],array_values($r));
