function lp_resource_list(array $rows): void {foreach($rows as $r){echo '<h4>'.e($r['title']).'</h4>';if(filter_var($r['url'],FILTER_VALIDATE_URL)&&parse_url($r['url'],PHP_URL_SCHEME)==='https')echo '<a href="'.e($r['url']).'" target="_blank" rel="noopener noreferrer">Open learning resource ↗</a>';echo '<p>'.e($r['notes']??'').'</p>';}if(!$rows)echo '<p>No learning resources shared yet.</p>';}
function lp_student_view(array $u,array $s,string $view): void {
 $tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$sid=(int)$s['id'];$class=(int)$s['class_id'];lp_card(ucwords($view));
 if($view==='dashboard'){
  $courses=lp_courses($u);$attendance=(int)g("SELECT COUNT(*) FROM attendance WHERE tenant_id=? AND student_id=? AND status='present'",[$tid,$sid]);$tasks=(int)g("SELECT COUNT(*) FROM lp_planner WHERE tenant_id=? AND user_id=? AND status='planned'",[$tid,$uid]);echo '<div class="lp-metrics">';foreach([['Published courses',count($courses)],['Present days recorded',$attendance],['Planned study tasks',$tasks]] as [$label,$n])echo '<div class="lp-metric">'.e($label).'<strong>'.(int)$n.'</strong></div>';echo '</div><p>Use Homework for learning activities, Grades for published results, and Study planner to organise your week.</p>';
 }
 elseif($view==='homework'||$view==='resources'){
