  else lp_table(q("SELECT l.lesson_date,c.topic,l.homework FROM ac_lessons l JOIN ac_curriculum c ON c.id=l.curriculum_id AND c.tenant_id=l.tenant_id WHERE l.tenant_id=? AND c.class_id=? AND c.session_name=? AND l.status='delivered' AND l.homework IS NOT NULL AND l.homework<>'' ORDER BY l.lesson_date DESC LIMIT 60",[$tid,$class,$s['session_name']])->fetchAll(),['Lesson date','Topic','Academic homework']);
  foreach(lp_courses($u) as $course){$lessons=q('SELECT * FROM lm_lessons WHERE tenant_id=? AND course_id=? AND (available_at IS NULL OR available_at<=?)'.($view==='homework'?" AND lesson_type IN ('homework','quiz')":'').' ORDER BY position,id LIMIT 100',[$tid,$course['id'],date('Y-m-d H:i:s')])->fetchAll();foreach($lessons as $l){
   echo '<article class="lp-card"><span class="lp-chip">'.e($course['title'].' · '.$l['lesson_type']).'</span><h3>'.e($l['title']).'</h3><p>'.e($l['content']).'</p>';if($l['resource_url']&&parse_url($l['resource_url'],PHP_URL_SCHEME)==='https')echo '<a href="'.e($l['resource_url']).'" target="_blank" rel="noopener noreferrer">Open resource ↗</a>';
   if(in_array($l['lesson_type'],['homework','quiz'],true)){
    $sub=q('SELECT id,answer,score,feedback,graded_at,filedata FROM lm_submissions WHERE tenant_id=? AND lesson_id=? AND student_id=?',[$tid,$l['id'],$sid])->fetch();echo '<p>Deadline (Africa/Lagos): '.e($l['due_at']?:'Not set').'</p>';if($sub){echo '<p>Your answer: '.e($sub['answer']).'</p><p>Score: '.e($sub['score']??'Awaiting grading').' / '.e($l['points']).' · '.e($sub['feedback']).'</p>';if($sub['filedata']!==null)echo '<a href="?s=learning&amp;lp_file='.(int)$sub['id'].'">Download your attachment</a>';}
    if((!$l['due_at']||$l['due_at']>=date('Y-m-d H:i:s'))&&(!$sub||!$sub['graded_at'])){lp_form('submit');lp_hidden('lesson_id',(int)$l['id']);lp_input('answer','Your work','textarea',(string)($sub['answer']??''),false);lp_input('attachment','Optional PDF/image/text attachment, up to 2 MB','file','',false);lp_end('Submit homework');}
   }
   lp_form('complete');lp_hidden('lesson_id',(int)$l['id']);lp_end('Mark activity completed');echo '</article>';
  }}
 }
 elseif($view==='grades'){
  lp_table(q("SELECT sub.name,r.score,r.max_score,r.grade,r.remark FROM results r JOIN subjects sub ON sub.id=r.subject_id AND sub.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.student_id=? AND r.status='published' ORDER BY r.id DESC LIMIT 100",[$tid,$sid])->fetchAll(),['Subject','Score','Maximum','Grade','Remark']);
  lp_table(q("SELECT a.session_name,a.term_name,sub.name subject,a.title,sc.score,a.max_score FROM ac_scores sc JOIN ac_assessments a ON a.id=sc.assessment_id AND a.tenant_id=sc.tenant_id JOIN subjects sub ON sub.id=a.subject_id AND sub.tenant_id=a.tenant_id JOIN ac_term_approvals p ON p.tenant_id=a.tenant_id AND p.class_id=a.class_id AND p.session_name=a.session_name AND p.term_name=a.term_name WHERE sc.tenant_id=? AND sc.student_id=? AND sc.status='approved' AND p.status='published' ORDER BY a.id DESC LIMIT 100",[$tid,$sid])->fetchAll(),['Session','Term','Subject','Assessment','Score','Maximum']);
 }
 elseif($view==='attendance'){
  lp_table(q('SELECT attendance_date,status,reason FROM attendance WHERE tenant_id=? AND student_id=? ORDER BY attendance_date DESC LIMIT 100',[$tid,$sid])->fetchAll(),['Date','Status','Reason']);lp_table(q('SELECT attendance_date,period_name,status FROM aw_period_attendance WHERE tenant_id=? AND student_id=? ORDER BY attendance_date DESC LIMIT 100',[$tid,$sid])->fetchAll(),['Date','Period','Status']);
 }
 elseif($view==='feedback')lp_table(q('SELECT l.title,s.score,l.points,s.feedback,s.graded_at FROM lm_submissions s JOIN lm_lessons l ON l.id=s.lesson_id AND l.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.student_id=? AND s.graded_at IS NOT NULL ORDER BY s.graded_at DESC LIMIT 100',[$tid,$sid])->fetchAll(),['Activity','Score','Maximum','Teacher feedback','Reviewed']);
 elseif($view==='announcements'){
  if(lp_has('cm_posts')){foreach(q('SELECT * FROM cm_posts WHERE tenant_id=? ORDER BY pinned DESC,id DESC LIMIT 200',[$tid])->fetchAll() as $post)if(cmAllowed($post,'student',$uid,$tid))echo '<article><h3>'.e($post['title']).'</h3><p>'.e($post['body']).'</p></article>';}
  echo '<p><a href="?s=announcements">Open Community Hub →</a></p>';
 }
 elseif($view==='clubs'){
  foreach(q('SELECT * FROM lp_clubs WHERE tenant_id=? AND active=1 AND (class_id IS NULL OR class_id=?) ORDER BY title',[$tid,$class])->fetchAll() as $club){echo '<h3>'.e($club['title']).'</h3><p>'.e($club['description']).'</p>';$status=g('SELECT status FROM lp_club_members WHERE tenant_id=? AND club_id=? AND student_id=?',[$tid,$club['id'],$sid]);if($status)echo '<p>Membership: '.e($status).'</p>';else{lp_form('join_club');lp_hidden('club_id',(int)$club['id']);lp_end('Request to join');}}
 }
 elseif($view==='library'){
  foreach(q('SELECT id,title,author,available FROM books WHERE tenant_id=? ORDER BY title LIMIT 200',[$tid])->fetchAll() as $book){echo '<h4>'.e($book['title']).' · '.e($book['author']).'</h4><p>Copies available: '.(int)$book['available'].'</p>';if((int)$book['available']>0){lp_form('borrow');lp_hidden('book_id',(int)$book['id']);lp_end('Request library loan');}}
  lp_table(q('SELECT b.title,l.status,l.due_on,l.returned_at FROM lp_library_loans l JOIN books b ON b.id=l.book_id AND b.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.student_id=? ORDER BY l.id DESC LIMIT 100',[$tid,$sid])->fetchAll(),['Book','Status','Due on','Returned']);
 }
 elseif($view==='badges')lp_table(q('SELECT b.label,c.title,b.awarded_at FROM lm_badges b JOIN lm_courses c ON c.id=b.course_id AND c.tenant_id=b.tenant_id WHERE b.tenant_id=? AND b.student_id=? ORDER BY b.awarded_at DESC LIMIT 100',[$tid,$sid])->fetchAll(),['Badge','Course','Awarded']);
 elseif($view==='planner'){
  lp_form('planner');lp_input('title','Study goal / task');lp_input('due_on','Target date','date');lp_end('Add study task');foreach(q('SELECT * FROM lp_planner WHERE tenant_id=? AND user_id=? AND student_id=? ORDER BY due_on,id DESC LIMIT 100',[$tid,$uid,$sid])->fetchAll() as $task){echo '<p>'.e($task['title'].' · '.$task['due_on'].' · '.$task['status']).'</p>';if($task['status']==='planned'){lp_form('planner_done');lp_hidden('task_id',(int)$task['id']);lp_end('Complete task');}}
 }
 elseif($view==='cbt')lp_cbt_view($u,$s);
 echo '</section>';
}
function lp_cbt_view(array $u,array $s): void {
 $tid=(int)$u['tenant_id'];$sid=(int)$s['id'];$id=(int)($_GET['attempt']??0);
 if($id){
  $a=cbAttempt($tid,$id);if((int)$a['user_id']!==(int)$u['id']||(int)$a['student_id']!==$sid)throw new RuntimeException('Attempt unavailable.');
  if(!$a['submitted_at']&&$a['expires_at']<=date('Y-m-d H:i:s')){lp_cbt_save($u,$id,[],true);$a=cbAttempt($tid,$id);}
  $x=cbExam($tid,(int)$a['exam_id']);echo '<h3>'.e($x['title']).'</h3>';
  if($a['submitted_at']){echo '<p>Attempt submitted. '.($x['results_published']?'Published result: '.e($a['score']).' / '.e($a['max_score']):'Results await school publication.').'</p>';return;}
  echo '<div class="lp-timer">Exam time remaining: <span id="lp-clock" data-end="'.e((new DateTimeImmutable($a['expires_at']))->format(DATE_ATOM)).'">Timer running</span></div>';lp_form('cbt_save');lp_hidden('attempt_id',$id);
  $rows=q('SELECT q.id,q.kind,q.body,q.options_json,q.points,a.response FROM cb_questions q JOIN cb_answers a ON a.question_id=q.id AND a.tenant_id=q.tenant_id WHERE a.tenant_id=? AND a.attempt_id=?',[$tid,$id])->fetchAll();$map=array_column($rows,null,'id');
  foreach(json_decode($a['question_order_json'],true) as $qid){if(!isset($map[$qid]))continue;$r=$map[$qid];echo '<article class="lp-card"><p>'.e($r['body']).'</p><small>'.e($r['points']).' points</small>';
   if(in_array($r['kind'],['mcq','truefalse'],true)){$options=$r['kind']==='truefalse'?['True','False']:json_decode($r['options_json']?:'[]',true);echo '<label>Your answer<select name="answers['.(int)$qid.']"><option value="">Choose an answer</option>';foreach($options as $o)echo '<option value="'.e($o).'" '.($r['response']===$o?'selected':'').'>'.e($o).'</option>';echo '</select></label>';}
   else echo '<label>Your answer<textarea name="answers['.(int)$qid.']" rows="4">'.e($r['response']).'</textarea></label>';echo '</article>';
  }
  echo '<div><button class="btn">Save answers</button> <button class="btn" type="submit" onclick="this.form.elements.lp_action.value=\'cbt_submit\'">Submit final answers</button></div></form><p>The timer continues while you are away. Answers are saved when you press Save; save regularly.</p>';
  echo '<script>(()=>{const el=document.getElementById("lp-clock");const form=el.closest("section").querySelector("form");let sent=false;const tick=()=>{const seconds=Math.max(0,Math.ceil((Date.parse(el.dataset.end)-Date.now())/1000));el.textContent=Math.floor(seconds/60)+"m "+seconds%60+"s";if(seconds===0&&!sent){sent=true;form.elements.lp_action.value="cbt_submit";form.requestSubmit();}};tick();setInterval(tick,1000);})();</script>';
  return;
 }
 foreach(q('SELECT id,title,duration_minutes,starts_at,ends_at FROM cb_exams WHERE tenant_id=? AND class_id=? AND published=1 ORDER BY id DESC',[$tid,$s['class_id']])->fetchAll() as $x){echo '<h4>'.e($x['title']).'</h4><p>'.e($x['duration_minutes']).' minutes · Opens '.e($x['starts_at']?:'now').' · Closes '.e($x['ends_at']?:'not set').'</p>';lp_form('cbt_start');lp_hidden('exam_id',(int)$x['id']);lp_input('code','Access code (if provided)','text','',false);lp_end('Start / resume exam');}
 $attempts=q('SELECT a.id,x.title,a.status,a.score,a.max_score,x.results_published FROM cb_attempts a JOIN cb_exams x ON x.id=a.exam_id AND x.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.user_id=? AND a.student_id=? ORDER BY a.id DESC LIMIT 50',[$tid,$u['id'],$sid])->fetchAll();foreach($attempts as $a)echo '<p><a href="?s=learning&amp;view=cbt&amp;attempt='.(int)$a['id'].'">'.e($a['title']).' · '.e($a['status']).'</a>'.($a['results_published']?' · '.e($a['score']).' / '.e($a['max_score']):'').'</p>';
}
function lp_manage(array $u): void {
 $tid=(int)$u['tenant_id'];echo '<h3>School controls and approvals</h3><p>Manage teacher allocations and timetable in <a href="?s=academics">Academics</a>. Review/approve scores there before publishing results. Teacher IDs in academic allocations are portal user IDs.</p>';
 $currentAi=q('SELECT * FROM lp_ai_settings WHERE tenant_id=?',[$tid])->fetch()?:[];lp_form('ai_settings');echo '<label>Teacher AI enabled<input type="checkbox" name="teachers_enabled" value="1" '.(!empty($currentAi['teachers_enabled'])?'checked':'').'></label><label>Student AI enabled (school approval)<input type="checkbox" name="students_enabled" value="1" '.(!empty($currentAi['students_enabled'])?'checked':'').'></label>';lp_input('daily_limit','Daily requests per account (1–20)','number',(string)($currentAi['daily_limit']??5));lp_end('Save AI controls');$settings=q('SELECT teachers_enabled,students_enabled,daily_limit FROM lp_ai_settings WHERE tenant_id=?',[$tid])->fetchAll();lp_table($settings,['Teacher enabled','Student enabled','Daily limit']);echo '<p>AI uses the private providers.ai_api_key in config.php. Never enter a secret in a message or public form. Disabled until explicitly enabled by the school. Provider failures count against quota.</p>';
 lp_form('club');lp_input('title','Club name');lp_input('description','Description','textarea');$classes=[0=>'All classes']+lp_choices(q('SELECT id,name FROM classes WHERE tenant_id=? ORDER BY name',[$tid])->fetchAll(),'name');lp_select('class_id','Class audience',$classes);lp_input('capacity','Capacity','number','30');lp_end('Create club');
 foreach(q("SELECT m.*,s.name,c.title FROM lp_club_members m JOIN students s ON s.id=m.student_id AND s.tenant_id=m.tenant_id JOIN lp_clubs c ON c.id=m.club_id AND c.tenant_id=m.tenant_id WHERE m.tenant_id=? AND m.status='pending' ORDER BY m.id LIMIT 100",[$tid])->fetchAll() as $r){echo '<p>Club request: '.e($r['name'].' · '.$r['title']).'</p>';lp_form('review_member');lp_hidden('member_id',(int)$r['id']);lp_select('decision','Decision',['approved'=>'Approve','rejected'=>'Reject']);lp_end('Review membership');}
 foreach(q("SELECT l.*,s.name,b.title FROM lp_library_loans l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id JOIN books b ON b.id=l.book_id AND b.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.status IN ('requested','issued') ORDER BY l.id LIMIT 100",[$tid])->fetchAll() as $r){echo '<p>Library: '.e($r['name'].' · '.$r['title'].' · '.$r['status']).'</p>';lp_form('review_loan');lp_hidden('loan_id',(int)$r['id']);lp_select('decision','Decision',$r['status']==='issued'?['returned'=>'Mark returned']:['issued'=>'Issue copy','rejected'=>'Reject request']);lp_input('due_on','Due date (required when issuing)','date','',false);lp_end('Update library loan');}
 foreach(q("SELECT * FROM lp_corrections WHERE tenant_id=? AND status='pending' ORDER BY id LIMIT 100",[$tid])->fetchAll() as $r){echo '<p>Correction #'.(int)$r['id'].' · Score #'.(int)$r['score_id'].' · '.e($r['previous_score']).' → '.e($r['new_score']).' · '.e($r['reason']).'</p>';lp_form('review_correction');lp_hidden('correction_id',(int)$r['id']);lp_select('decision','Decision',['applied'=>'Apply to unpublished result for fresh moderation','rejected'=>'Reject']);lp_input('review_note','Review note','textarea');lp_end('Review correction');}
 foreach(q("SELECT l.*,u.name FROM aw_leave l JOIN users u ON u.id=l.person_id AND u.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.person_type='staff' AND l.status='pending' ORDER BY l.id LIMIT 100",[$tid])->fetchAll() as $r){echo '<p>Leave: '.e($r['name'].' · '.$r['starts_on'].' – '.$r['ends_on'].' · '.$r['reason']).'</p>';lp_form('review_leave');lp_hidden('leave_id',(int)$r['id']);lp_select('decision','Decision',['approved'=>'Approve','rejected'=>'Reject']);lp_end('Review leave');}
 foreach(q("SELECT p.*,u.name FROM lp_pd p JOIN users u ON u.id=p.user_id AND u.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.status='submitted' ORDER BY p.id LIMIT 100",[$tid])->fetchAll() as $r){echo '<p>Professional development: '.e($r['name'].' · '.$r['title'].' · '.$r['hours'].' hours · '.$r['provider']).'</p>';if($r['evidence_url'])echo '<a href="'.e(lp_url($r['evidence_url'])).'" target="_blank" rel="noopener noreferrer">View evidence ↗</a>';lp_form('review_pd');lp_hidden('pd_id',(int)$r['id']);lp_select('decision','Decision',['approved'=>'Approve','rejected'=>'Reject']);lp_end('Review development record');}
 echo '<p><a href="?s=attendance&amp;tab=cases">Review confidential incidents in Attendance & Welfare →</a></p>';
}
